/*
 * Modified by Actuna Sp. z o.o.:
 *   new module (#75, #76): the text of an error value for the log - it never throws and is
 *   always a string, also for undefined, null and values that cannot be converted to a
 *   string; the text of every value that is printed today (every Error) stays the same
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

/**
 * The text of an error value for the log (#75, #76).
 *
 * A rejection or an exception can carry any value: `undefined` (`reject()`), `null`, an
 * object without a prototype, an object whose `toString` or `message` throws, a Proxy.
 * Reporting such a value with `err.toString()` or `String(err)` throws again, and that
 * exception ends the operation that only wanted to log the error.
 *
 * The functions below never throw and always return a string. The text of every value
 * that can be printed is the same as the text of the expression it replaces. The content
 * of objects is never printed (no inspect, no JSON): an object gives its own text, such as
 * "[object Object]", as before.
 *
 * This module has no dependencies, so that any module of the runtime can use it
 * without a cycle. It is internal: not a part of RED.util or of the node API.
 */

/**
 * The text used when a value cannot be converted to a string. Not translated.
 */
const NOT_PRINTABLE = "(the value cannot be printed)";

/**
 * The text of `err.toString()` - for the places that logged `err.toString()`.
 *
 * - `undefined`, `null`: `"undefined"`, `"null"` (no property is read);
 * - `toString()` returns a string: that string, unchanged (`Error: s`, `text`, `42`);
 * - `toString()` returns `undefined` or `null`: `""`;
 * - `toString()` returns another value: `"" + value`;
 * - anything that throws (no `toString`, a throwing `toString` or getter, a Proxy, a
 *   result that cannot be converted): NOT_PRINTABLE.
 *
 * `toString` is read and called at most once.
 * @param {*} err - any value
 * @return {String}
 */
function errorText(err) {
    if (err === undefined || err === null) {
        return String(err);
    }
    try {
        const text = err.toString();
        if (typeof text === "string") {
            return text;
        }
        if (text === undefined || text === null) {
            return "";
        }
        return "" + text;
    } catch (e) {
        return NOT_PRINTABLE;
    }
}

/**
 * The text of the message of an error - for the places that logged
 * `(err && err.message) || String(err)`.
 *
 * - `undefined`, `null`: `"undefined"`, `"null"` (no property is read);
 * - a truthy `message` (read once): the message, as a string (`Error("s")` gives `"s"`);
 * - a falsy `message`: `String(err)` (`Error("")` gives `"Error"`, `{}` gives
 *   `"[object Object]"`, `Symbol("x")` gives `"Symbol(x)"`);
 * - anything that throws (a throwing getter, a Proxy, a value that cannot be
 *   converted): NOT_PRINTABLE.
 * @param {*} err - any value
 * @return {String}
 */
function messageText(err) {
    if (err === undefined || err === null) {
        return String(err);
    }
    try {
        const message = err.message;
        if (message) {
            return typeof message === "string" ? message : "" + message;
        }
        return String(err);
    } catch (e) {
        return NOT_PRINTABLE;
    }
}

module.exports = {
    NOT_PRINTABLE: NOT_PRINTABLE,
    errorText: errorText,
    messageText: messageText
};
